<?php $title='Boutique'; $subtitle='Gérez vos produits, vos stocks et les ventes au comptoir.'; $section='shop'; require __DIR__.'/management_header.php'; ?>
<div class="management-grid"><?php if ($canSell): ?><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='sale' ? 'open' : '' ?>><summary>+ Enregistrer une vente</summary><form method="post" action="shop" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="sale"><input type="hidden" name="request_token" value="<?= e($requestToken) ?>"><label>Produit *<select name="product_id" required><option value="">Sélectionner</option><?php foreach ($products as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>|<?= e(ShopSaleService::productVersion($p)) ?>" <?= explode('|',is_string($_POST['product_id'] ?? null) ? $_POST['product_id'] : '')[0]===(string)$p['id'] ? 'selected' : '' ?>><?= e($p['name'].' · '.dt($p['price']).' · stock '.$p['stock']) ?></option><?php endforeach; ?></select></label><label>Quantité *<input type="number" name="quantity" min="1" max="1000000" value="<?= e(($_POST['action'] ?? '')==='sale' ? ($_POST['quantity'] ?? '1') : '1') ?>" required></label><label>Moyen de paiement *<select name="method"><?php foreach (['espèces','chèque','virement','D17','Flouci','carte bancaire'] as $method): ?><option value="<?= e($method) ?>" <?= ($_POST['method'] ?? '')===$method?'selected':'' ?>><?= e(ucfirst($method)) ?></option><?php endforeach; ?></select></label><p class="form-hint">Une vente porte sur un seul produit. Si le prix ou le produit change, vérifiez les informations actualisées avant de recommencer. Une nouvelle soumission identique ne crée pas une deuxième vente.</p><div class="form-actions"><button class="primary">Valider la vente</button></div></form></details><?php endif; ?>
<?php if ($canManage): ?><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='product' ? 'open' : '' ?>><summary>+ Ajouter un produit</summary><form method="post" action="shop" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="product"><label>Nom *<input name="name" maxlength="120" required value="<?= e($_POST['name'] ?? '') ?>"></label><label>Référence unique *<input name="sku" maxlength="50" required value="<?= e($_POST['sku'] ?? '') ?>"></label><label>Prix unitaire (DT) *<input type="number" name="price" min="0" max="9999999.999" step="0.001" required value="<?= e($_POST['price'] ?? '') ?>"></label><label>Stock initial *<input type="number" name="stock" min="0" max="1000000" required value="<?= e($_POST['stock'] ?? '0') ?>"></label><label>Seuil d’alerte *<input type="number" name="threshold" min="0" max="1000000" required value="<?= e($_POST['threshold'] ?? '5') ?>"></label><div class="form-actions"><button class="primary">Créer le produit</button></div></form></details><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='restock' ? 'open' : '' ?>><summary>+ Réapprovisionner</summary><form method="post" action="shop" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="restock"><label>Produit *<select name="product_id" required><option value="">Sélectionner</option><?php foreach ($products as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name'].' · stock '.$p['stock']) ?></option><?php endforeach; ?></select></label><label>Quantité reçue *<input type="number" name="quantity" min="1" max="1000000" required></label><div class="form-actions"><button class="primary">Ajouter au stock</button></div></form></details><?php endif; ?></div>
<section class="card management-table"><div class="card-head"><div><h3>Catalogue & stocks</h3><p>L’alerte apparaît lorsque le stock atteint ou descend sous son seuil.</p></div></div><div class="table-scroll"><table><thead><tr><th>PRODUIT</th><th>RÉFÉRENCE</th><th>PRIX</th><th>STOCK</th><th>SEUIL</th><th>ÉTAT</th><th>ACTION</th></tr></thead><tbody><?php foreach ($products as $p): ?><tr><td><strong><?= e($p['name']) ?></strong></td><td><?= e($p['sku']) ?></td><td><?= e(dt($p['price'])) ?></td><td><?= (int)$p['stock'] ?></td><td><?= (int)$p['low_stock_threshold'] ?></td><td><span class="status <?= !$p['is_active'] || (int)$p['stock'] <= (int)$p['low_stock_threshold'] ? 'expired' : '' ?>"><?= !$p['is_active'] ? 'Inactif' : ((int)$p['stock']===0 ? 'Rupture' : ((int)$p['stock'] <= (int)$p['low_stock_threshold'] ? 'Stock bas' : 'Disponible')) ?></span></td><td><a class="text-link" href="shop?product=<?= (int)$p['id'] ?>">Détails</a></td></tr><?php endforeach; ?><?php if (!$products): ?><tr><td colspan="7" class="empty">Aucun produit pour le moment.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if ($selectedProduct): ?>
<section class="card management-table"><div class="card-head"><div><h3><?= e($selectedProduct['name']) ?> · <?= e($selectedProduct['sku']) ?></h3><p>Stock actuel : <?= (int)$selectedProduct['stock'] ?> unité(s) · <?= $selectedProduct['is_active'] ? 'Produit actif' : 'Produit inactif' ?></p></div><a class="text-link" href="shop">Fermer</a></div>
<?php if ($canManage): ?><div class="management-grid inventory-actions"><details class="form-card" <?= $error && ($_POST['action'] ?? '')==='edit_product' ? 'open' : '' ?>><summary>Modifier le produit</summary><form method="post" action="shop?product=<?= (int)$selectedProduct['id'] ?>" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="edit_product"><input type="hidden" name="product_id" value="<?= (int)$selectedProduct['id'] ?>"><label>Nom *<input name="name" maxlength="120" value="<?= e(($_POST['action'] ?? '')==='edit_product' ? ($_POST['name'] ?? '') : $selectedProduct['name']) ?>" required></label><label>Référence *<input name="sku" maxlength="50" value="<?= e(($_POST['action'] ?? '')==='edit_product' ? ($_POST['sku'] ?? '') : $selectedProduct['sku']) ?>" required></label><label>Prix unitaire (DT) *<input type="number" name="price" min="0" max="9999999.999" step="0.001" value="<?= e(($_POST['action'] ?? '')==='edit_product' ? ($_POST['price'] ?? '') : $selectedProduct['price']) ?>" required></label><label>Seuil d’alerte *<input type="number" name="threshold" min="0" max="1000000" value="<?= e(($_POST['action'] ?? '')==='edit_product' ? ($_POST['threshold'] ?? '') : $selectedProduct['low_stock_threshold']) ?>" required></label><p class="form-hint">Les nouvelles ventes conservent le nom, la référence et le prix au moment de la vente. Les anciennes ventes affichent le nom actuel.</p><div class="form-actions"><button class="primary">Enregistrer</button></div></form></details>
<details class="form-card" <?= $error && ($_POST['action'] ?? '')==='adjust' ? 'open' : '' ?>><summary>Corriger le stock</summary><form method="post" action="shop?product=<?= (int)$selectedProduct['id'] ?>" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="adjust"><input type="hidden" name="product_id" value="<?= (int)$selectedProduct['id'] ?>"><input type="hidden" name="expected_stock" value="<?= (int)$selectedProduct['stock'] ?>"><label>Quantité physiquement comptée *<input type="number" name="counted" min="0" max="1000000" required value="<?= e(($_POST['action'] ?? '')==='adjust' ? ($_POST['counted'] ?? '') : (string)$selectedProduct['stock']) ?>"></label><label>Motif de correction *<input name="note" maxlength="255" required value="<?= e(($_POST['action'] ?? '')==='adjust' ? ($_POST['note'] ?? '') : '') ?>" placeholder="Inventaire, casse…"></label><p class="form-hint">Le stock sera remplacé par la quantité comptée et l’écart sera historisé. Si le stock a changé entre-temps, la correction sera refusée.</p><div class="form-actions"><button class="primary" type="submit" data-confirm="Corriger le stock avec la quantité comptée ?" onclick="return confirm(this.dataset.confirm)">Corriger le stock</button></div></form></details></div>
<form method="post" action="shop?product=<?= (int)$selectedProduct['id'] ?>" class="inventory-toggle"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="toggle_product"><input type="hidden" name="product_id" value="<?= (int)$selectedProduct['id'] ?>"><input type="hidden" name="active" value="<?= $selectedProduct['is_active'] ? '0' : '1' ?>"><button class="btn btn-outline" type="submit" data-confirm="<?= $selectedProduct['is_active'] ? 'Désactiver ce produit et empêcher sa vente ?' : 'Réactiver ce produit ?' ?>" onclick="return confirm(this.dataset.confirm)"><?= $selectedProduct['is_active'] ? 'Désactiver le produit' : 'Réactiver le produit' ?></button></form><?php endif; ?>
<h3 class="inventory-history-title">Historique des mouvements</h3><p class="form-hint">Les 100 derniers mouvements de ce produit. <a class="text-link" href="stock_history?id=<?= (int)$selectedProduct['id'] ?>">Voir tout l’historique et filtrer</a></p><div class="table-scroll"><table><thead><tr><th>DATE</th><th>TYPE</th><th>ÉCART</th><th>MOTIF</th><th>SAISI PAR</th></tr></thead><tbody><?php $movementLabels=['initial'=>'Stock initial','restock'=>'Réapprovisionnement','sale'=>'Vente','adjustment'=>'Correction']; foreach ($movements as $movement): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($movement['created_at']))) ?></td><td><?= e($movementLabels[$movement['reason']] ?? $movement['reason']) ?></td><td><?= (int)$movement['quantity_change'] > 0 ? '+' : '' ?><?= (int)$movement['quantity_change'] ?></td><td><?= e($movement['note'] ?? '—') ?></td><td><?= e($movement['author'] ?: '—') ?></td></tr><?php endforeach; ?><?php if (!$movements): ?><tr><td colspan="5" class="empty">Aucun mouvement enregistré.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Ventes boutique</h3><p><?= $total ?> vente(s) · <?= e(date('d/m/Y',strtotime($date))) ?></p></div><strong class="cash-total"><?= e(dt($salesTotal)) ?></strong></div><form action="shop" class="search-form" method="get"><label for="shop-date">Date</label><input id="shop-date" type="date" name="date" value="<?= e($date) ?>"><button class="primary">Afficher</button></form><div class="table-scroll"><table><thead><tr><th>HEURE</th><th>PRODUIT</th><th>QUANTITÉ</th><th>PRIX UNIT.</th><th>TOTAL</th><th>MOYEN</th><th>VENDEUR</th><th>REÇU</th></tr></thead><tbody><?php foreach ($sales as $sale): ?><tr><td><?= e(date('H:i',strtotime($sale['sold_at']))) ?></td><td><?= e($sale['name']) ?></td><td><?= (int)$sale['quantity'] ?></td><td><?= e(dt($sale['unit_price'])) ?></td><td><?= e(dt($sale['total'])) ?></td><td><?= e(ucfirst($sale['method'])) ?></td><td><?= e($sale['seller'] ?: '—') ?></td><td><a class="text-link" href="shop_receipt?id=<?= (int)$sale['id'] ?>">Voir le reçu</a></td></tr><?php endforeach; ?><?php if (!$sales): ?><tr><td colspan="8" class="empty">Aucune vente pour cette date.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="shop?date=<?= e($date) ?>&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="shop?date=<?= e($date) ?>&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div><p class="form-hint">Ces ventes sont séparées de la caisse des abonnements et ne sont pas encore incluses dans les revenus du tableau de bord.</p></section>
